// State shape: { rooms: { [roomId]: { messages: [], unread: number } }, currentRoomId }
function reducer(state, action) {
  switch (action.type) {
    case 'SEND_MESSAGE':
      return {
        ...state,
        rooms: {
          ...state.rooms,
          [state.currentRoomId]: {
            ...state.rooms[state.currentRoomId],
            messages: [
              ...state.rooms[state.currentRoomId].messages,
              { id: action.payload.tempId, text: action.payload.text, status: 'pending' }
            ]
          }
        }
      };
    case 'ACK_MESSAGE':
      // Replace temp message with confirmed message
      // ...
    case 'ROLLBACK_MESSAGE':
      // Remove failed message
      // ...
    default:
      return state;
  }
}

// Memoized selector
const useRoomMessages = (roomId) => {
  return useMemo(() => {
    const room = state.rooms[roomId];
    return { 
      unread: room.unread, 
      lastMessages: room.messages.slice(-20) 
    };
  }, [state.rooms[roomId]]);
};

// Memoized message item
const MessageItem = React.memo(({ message }) => (
  <div className={message.status}>{message.text}</div>
));
```

